## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/gastroparesisLogic.ts`

```typescript
/**
 * Gastroparesis Clinical Logic Engine
 * Based on: AGA Clinical Guideline on the Management of Gastroparesis (2022, 2025 Update)
 *           ACG Clinical Guideline: Gastroparesis (2022)
 *           AGA Technical Review on Gastroparesis (2022)
 * Key decisions: Diagnosis confirmation (4-hour GES), etiology identification,
 *                dietary modification, medication hierarchy (metoclopramide, domperidone,
 *                erythromycin), gastric electrical stimulation, pyloroplasty/G-POEM
 */

export type GastroparesisEtiology =
  | 'diabetic'
  | 'post_surgical'
  | 'idiopathic'
  | 'post_viral'
  | 'connective_tissue'
  | 'parkinson'
  | 'unknown';

export type GastroparesisSeverity = 'mild' | 'moderate' | 'severe';

export type DiagnosticStatus =
  | 'not_tested'
  | 'ges_4h_confirmed' // 4-hour gastric emptying scintigraphy
  | 'ges_2h_only' // 2-hour study only — insufficient
  | 'wireless_motility_capsule'
  | 'breath_test'
  | 'clinical_diagnosis_only';

export interface GastroparesisInput {
  // Diagnosis
  diagnosticStatus: DiagnosticStatus;
  gastricRetentionPercent4h?: number; // >10% at 4h = abnormal; >35% = moderate-severe
  gastricRetentionPercent2h?: number;
  hasNausea: boolean;
  hasVomiting: boolean;
  hasEarlyFullness: boolean;
  hasPostprandialFullness: boolean;
  hasAbdominalPain: boolean; // predominant pain = poor predictor of GES response
  gcsiScore?: number; // Gastroparesis Cardinal Symptom Index (0–5)

  // Etiology
  etiology: GastroparesisEtiology;
  hasType1Diabetes: boolean;
  hasType2Diabetes: boolean;
  hba1cPercent?: number;
  hasPriorGastricSurgery: boolean;
  priorSurgeryType?: string;

  // Severity
  severity: GastroparesisSeverity;
  hasHospitalizationsInPastYear: boolean;
  hospitalizationCount?: number;
  hasWeightLoss: boolean;
  weightLossKg?: number;
  hasDehydration: boolean;
  requiresNutritionalSupport: boolean;

  // Current medications
  isOnMetoclopramide: boolean;
  isOnDomperidone: boolean; // not FDA-approved in US; available via compassionate use
  isOnErythromycin: boolean;
  isOnProkinetic: boolean;
  isOnAntiemetic: boolean;
  isOnOpioids: boolean; // opioids worsen gastroparesis
  isOnAnticholinergics: boolean; // worsen gastroparesis
  isOnGLP1Agonist: boolean; // GLP-1 agonists delay gastric emptying

  // Comorbidities
  hasQTProlongation: boolean; // metoclopramide/domperidone risk
  hasTardivedyskinesia: boolean; // metoclopramide contraindicated
  hasParkinson: boolean;
  hasAnxietyDepression: boolean;
  hasNarcoticBowelSyndrome: boolean;

  // Prior interventions
  hasPriorGES: boolean; // gastric electrical stimulation (Enterra)
  hasPriorPyloroplasty: boolean;
  hasPriorGPOEM: boolean; // G-POEM (gastric peroral endoscopic myotomy)
  hasPriorBotoxInjection: boolean;
  hasPriorDietaryModification: boolean;
}

export interface GastroparesisRecommendation {
  primaryRecommendation: string;
  diagnosticPlan: string;
  dietaryModification: string;
  pharmacotherapy: string;
  interventionalOptions: string;
  nutritionalSupport: string;
  medicationsToAvoid: string[];
  urgentFlags: string[];
  recommendedAgents: string[];
  nextSteps: string[];
  evidenceLevel: 'A' | 'B' | 'C';
  rationale: string;
  references: Array<{ citation: string; pmid?: string; url?: string }>;
}

export function assessGastroparesis(input: GastroparesisInput): GastroparesisRecommendation {
  const urgentFlags: string[] = [];
  const recommendedAgents: string[] = [];
  const medicationsToAvoid: string[] = [];
  const nextSteps: string[] = [];

  // ─── Urgent Flags ─────────────────────────────────────────────────────────
  if (input.hasDehydration || (input.severity === 'severe' && input.hasVomiting)) {
    urgentFlags.push('Severe dehydration/vomiting: IV fluid resuscitation and electrolyte replacement required — consider hospitalization');
  }
  if (input.requiresNutritionalSupport && input.weightLossKg !== undefined && input.weightLossKg > 5) {
    urgentFlags.push(`Significant weight loss (${input.weightLossKg}kg): nutritional assessment and enteral nutrition support required`);
  }
  if (input.isOnOpioids) {
    urgentFlags.push('OPIOIDS: strongly worsen gastroparesis — opioid-induced gastroparesis is a recognized entity. Opioid taper/discontinuation is a priority.');
    medicationsToAvoid.push('Opioids — significantly delay gastric emptying; taper and discontinue if possible');
  }
  if (input.isOnGLP1Agonist) {
    urgentFlags.push('GLP-1 agonists (semaglutide, liraglutide, tirzepatide) delay gastric emptying — consider dose reduction or discontinuation in symptomatic gastroparesis');
    medicationsToAvoid.push('GLP-1 agonists — delay gastric emptying; reassess risk-benefit in gastroparesis');
  }
  if (input.isOnAnticholinergics) {
    medicationsToAvoid.push('Anticholinergic medications — delay gastric emptying; review and discontinue if possible');
  }
  if (input.hasTardivedyskinesia) {
    urgentFlags.push('Tardive dyskinesia: metoclopramide is CONTRAINDICATED — do not use');
    medicationsToAvoid.push('Metoclopramide — contraindicated with tardive dyskinesia');
  }
  if (input.hasQTProlongation) {
    urgentFlags.push('QT prolongation: metoclopramide and domperidone increase QT — use with caution or avoid; obtain baseline ECG');
    medicationsToAvoid.push('Metoclopramide, domperidone — QT-prolonging; caution with QT prolongation');
  }
  if (input.etiology === 'diabetic' && input.hba1cPercent !== undefined && input.hba1cPercent > 9) {
    urgentFlags.push(`Poorly controlled diabetes (HbA1c ${input.hba1cPercent}%): glycemic optimization is critical — hyperglycemia acutely worsens gastric motility. Target HbA1c <8%.`);
  }

  // ─── Diagnostic Plan ──────────────────────────────────────────────────────
  let diagnosticPlan = '';
  if (input.diagnosticStatus === 'not_tested' || input.diagnosticStatus === 'ges_2h_only') {
    diagnosticPlan =
      '4-HOUR GASTRIC EMPTYING SCINTIGRAPHY (GES) REQUIRED (AGA 2022 Strong Recommendation): ' +
      'The 4-hour study is the gold standard — 2-hour studies have poor sensitivity and are insufficient. ' +
      'Standardized protocol: 99mTc-sulfur colloid egg meal, images at 0, 1, 2, 4 hours. ' +
      'Hold prokinetics 48h before test. Hold opioids 48h before test. ' +
      'Abnormal: >10% retention at 4 hours (mild: 10–20%; moderate: 20–35%; severe: >35%). ' +
      'Alternative: wireless motility capsule (SmartPill) or 13C-octanoate breath test.';
    nextSteps.push('4-hour gastric emptying scintigraphy (standardized protocol)', 'Hold prokinetics and opioids 48h before test');
  } else if (input.diagnosticStatus === 'ges_4h_confirmed') {
    diagnosticPlan = `4-hour GES confirmed gastroparesis (${input.gastricRetentionPercent4h ?? '?'}% retention at 4h). Diagnosis established.`;
  } else {
    diagnosticPlan = 'Diagnosis established by alternative validated method. Confirm with 4-hour GES if clinical uncertainty.';
  }

  // ─── Dietary Modification ─────────────────────────────────────────────────
  const dietaryModification =
    'DIETARY MODIFICATION (first-line — AGA 2022): ' +
    '1) Small, frequent meals: 4–6 small meals/day instead of 3 large meals. ' +
    '2) Low-fat diet: fat delays gastric emptying — limit to <40g/day. ' +
    '3) Low-fiber diet: avoid indigestible fiber (raw vegetables, high-fiber foods) — risk of bezoar formation. ' +
    '4) Liquid-predominant diet: liquids empty faster than solids — use liquid nutritional supplements if needed. ' +
    '5) Avoid carbonated beverages. ' +
    '6) Eat sitting upright; avoid lying down for 2 hours after meals. ' +
    '7) Registered dietitian referral for individualized meal planning.';

  // ─── Pharmacotherapy ──────────────────────────────────────────────────────
  let pharmacotherapy = '';
  if (input.severity === 'mild' || !input.isOnProkinetic) {
    pharmacotherapy =
      'PHARMACOTHERAPY HIERARCHY (AGA 2022 — limited strong evidence): ' +
      '1) METOCLOPRAMIDE 5–10mg TID–QID (30 min before meals) — ONLY FDA-APPROVED PROKINETIC for gastroparesis. ' +
      '   Dopamine D2 antagonist + 5-HT4 agonist. ' +
      '   FDA Black Box Warning: tardive dyskinesia risk with >12 weeks use. ' +
      '   Limit to 12 weeks; reassess risk-benefit for longer use. ' +
      '   Contraindicated: tardive dyskinesia, Parkinson\'s disease, bowel obstruction. ' +
      '2) DOMPERIDONE 10mg TID–QID — peripheral D2 antagonist (less CNS penetration). ' +
      '   Not FDA-approved in US — available via FDA compassionate use IND. ' +
      '   Superior tolerability vs metoclopramide (less CNS side effects). ' +
      '   QT prolongation risk — baseline ECG required. ' +
      '3) ERYTHROMYCIN 125–250mg TID (before meals) — motilin receptor agonist. ' +
      '   Rapid tachyphylaxis (tolerance within 4 weeks). ' +
      '   Use for short-term acute exacerbations or IV in hospitalized patients. ' +
      '4) PRUCALOPRIDE (Motegrity) — 5-HT4 agonist: emerging evidence for gastroparesis. ' +
      '5) ANTIEMETICS for symptom control: ondansetron, promethazine, prochlorperazine. ' +
      '   Note: antiemetics treat symptoms but do not improve gastric emptying.';
    if (!input.hasTardivedyskinesia && !input.hasParkinson) {
      recommendedAgents.push('Metoclopramide 5–10mg TID–QID (FDA-approved — limit to 12 weeks)');
    }
    if (!input.hasQTProlongation) {
      recommendedAgents.push('Domperidone 10mg TID (via FDA compassionate use IND — superior tolerability)');
    }
    recommendedAgents.push(
      'Erythromycin 125–250mg TID (short-term/acute exacerbations)',
      'Ondansetron 4–8mg TID (antiemetic — symptom control)',
      'Prucalopride 2mg QD (5-HT4 agonist — emerging evidence)'
    );
  } else {
    pharmacotherapy =
      'Currently on prokinetic therapy. Assess response and tolerability. ' +
      'If inadequate response: optimize dose, switch prokinetic class, or consider interventional options. ' +
      'Therapeutic drug monitoring not applicable for prokinetics.';
  }

  // ─── Interventional Options ───────────────────────────────────────────────
  let interventionalOptions = '';
  if (input.severity === 'severe' || input.hasHospitalizationsInPastYear) {
    interventionalOptions =
      'INTERVENTIONAL OPTIONS for refractory/severe gastroparesis: ' +
      '1) GASTRIC PERORAL ENDOSCOPIC MYOTOMY (G-POEM): ' +
      '   Endoscopic pyloromyotomy — disrupts pyloric sphincter. ' +
      '   Emerging evidence: 80–90% clinical response in observational studies. ' +
      '   GALACTIC RCT (2023): G-POEM superior to sham procedure at 6 months. ' +
      '   Preferred over surgical pyloroplasty (less invasive). ' +
      '2) GASTRIC ELECTRICAL STIMULATION (GES — Enterra Therapy): ' +
      '   FDA humanitarian device exemption (HDE) for refractory diabetic/idiopathic gastroparesis. ' +
      '   Reduces vomiting and nausea (symptom benefit) but does NOT reliably improve gastric emptying. ' +
      '   Best evidence for diabetic gastroparesis with predominant nausea/vomiting. ' +
      '3) BOTULINUM TOXIN INJECTION (pylorus): ' +
      '   AGA 2022: NOT recommended — RCTs show no benefit over sham. ' +
      '4) SURGICAL PYLOROPLASTY: ' +
      '   Alternative to G-POEM; higher morbidity. ' +
      '5) TOTAL PARENTERAL NUTRITION (TPN): last resort for severe malnutrition — high complication risk.';
    if (!input.hasPriorGPOEM) {
      recommendedAgents.push('G-POEM (gastric peroral endoscopic myotomy) — preferred interventional option');
    }
    if (!input.hasPriorGES) {
      recommendedAgents.push('Gastric electrical stimulation (Enterra) — for refractory diabetic/idiopathic gastroparesis with predominant vomiting');
    }
  } else {
    interventionalOptions =
      'Interventional options not yet indicated — optimize dietary modification and pharmacotherapy first. ' +
      'Consider G-POEM or GES if refractory to medical management.';
  }

  // ─── Nutritional Support ──────────────────────────────────────────────────
  let nutritionalSupport = '';
  if (input.requiresNutritionalSupport || input.severity === 'severe') {
    nutritionalSupport =
      'NUTRITIONAL SUPPORT (AGA 2022): ' +
      '1) Oral liquid nutritional supplements first (Ensure, Boost, Carnation Breakfast Essentials). ' +
      '2) Jejunal feeding (NJ tube or PEJ): preferred over gastric feeding — bypasses gastroparesis. ' +
      '   Indicated for: weight loss >10%, inability to maintain oral intake, recurrent hospitalizations. ' +
      '3) Total parenteral nutrition (TPN): last resort — high infection/complication risk. ' +
      '   Only if enteral access not feasible.';
    nextSteps.push('Registered dietitian consultation for nutritional assessment', 'Consider jejunal feeding tube if oral intake inadequate');
  } else {
    nutritionalSupport = 'Oral diet with dietary modifications sufficient at this stage. Monitor weight and nutritional status.';
  }

  if (nextSteps.length === 0 || !nextSteps.some(s => s.includes('GES'))) {
    nextSteps.push(
      'Optimize glycemic control if diabetic (target HbA1c <8%)',
      'Review and discontinue medications that worsen gastric emptying (opioids, anticholinergics, GLP-1 agonists)',
      'Registered dietitian referral for dietary modification',
      'Gastroenterology/motility specialist referral'
    );
  }

  const rationale =
    `Etiology: ${input.etiology.replace(/_/g, ' ')}. ` +
    `Severity: ${input.severity}. ` +
    `Diagnostic status: ${input.diagnosticStatus.replace(/_/g, ' ')}. ` +
    `4h retention: ${input.gastricRetentionPercent4h ?? 'not measured'}%. ` +
    `On prokinetic: ${input.isOnProkinetic ? 'Yes' : 'No'}. ` +
    `Hospitalizations past year: ${input.hasHospitalizationsInPastYear ? 'Yes' : 'No'}.`;

  return {
    primaryRecommendation:
      input.diagnosticStatus === 'not_tested' || input.diagnosticStatus === 'ges_2h_only'
        ? '4-hour gastric emptying scintigraphy required for diagnosis — 2-hour studies are insufficient (AGA 2022 Strong Recommendation).'
        : input.severity === 'severe' || input.hasHospitalizationsInPastYear
        ? 'Severe/refractory gastroparesis: G-POEM or gastric electrical stimulation after failure of dietary + pharmacotherapy.'
        : 'Gastroparesis confirmed: dietary modification (small, low-fat, low-fiber meals) + metoclopramide (first-line pharmacotherapy).',
    diagnosticPlan,
    dietaryModification,
    pharmacotherapy,
    interventionalOptions,
    nutritionalSupport,
    medicationsToAvoid,
    urgentFlags,
    recommendedAgents,
    nextSteps,
    evidenceLevel: 'B',
    rationale,
    references: [
      {
        citation: 'Camilleri M, et al. Clinical Guideline: Management of Gastroparesis. Am J Gastroenterol. 2022;117(8):1197-1220.',
        pmid: '35767360',
        url: 'https://pubmed.ncbi.nlm.nih.gov/35767360/',
      },
      {
        citation: 'AGA Clinical Practice Guideline on the Pharmacological Management of Irritable Bowel Syndrome and Gastroparesis. Gastroenterology. 2022;163(6):1440-1471.',
        pmid: '36122912',
        url: 'https://pubmed.ncbi.nlm.nih.gov/36122912/',
      },
      {
        citation: 'Mekaroonkamol P, et al. Outcomes of Per Oral Endoscopic Pyloromyotomy in Gastroparesis Worldwide (GALACTIC). Gut. 2023;72(4):686-694.',
        pmid: '36202553',
        url: 'https://pubmed.ncbi.nlm.nih.gov/36202553/',
      },
      {
        citation: 'McCallum RW, et al. Gastric Electrical Stimulation with Enterra Therapy for Gastroparesis. Gastroenterology. 2010;138(7):2456-2462.',
        pmid: '20176023',
        url: 'https://pubmed.ncbi.nlm.nih.gov/20176023/',
      },
    ],
  };
}
